int Phot;
int LedStat;
String ND;

void setup() {
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  oled.clearDisplay();


  pinMode(2, OUTPUT);
  Phot = 0;
  LedStat = 0;
  drawStat();

}

void loop() {
  Phot = analogRead(A0);
  if (Phot >= 300) {
    LedStat = 1;
    digitalWrite(2, 1);
    ND = "Night";
  }
  if (Phot < 300) {
    LedStat = 0;
    digitalWrite(2, 0);
    ND = "Day";
  }
  drawStat();

}



  void drawStat() {
    oled.fillScreen(0);
    oled.setCursor(0, 0);
    oled.setTextColor(1);
    oled.setTextSize(1);
    oled.print("Light: ");
    oled.setCursor(20, 15);
    oled.setTextColor(1);
    oled.setTextSize(1);
    oled.print(Phot);
    oled.setCursor(0, 30);
    oled.setTextColor(1);
    oled.setTextSize(1);
    oled.print("Led stat");
    oled.setCursor(20, 55);
    oled.setTextColor(1);
    oled.setTextSize(1);
    oled.print(LedStat);
    oled.setCursor(60, 30);
    oled.setTextColor(1);
    oled.setTextSize(2);
    oled.print(ND);
    oled.display();
  }
